def extend(styles, families):
 import unicodedata
 for family,title,kind,rows in GROUPS:
  families.append((family,title,kind,rows))
  for i,(name,signature,topic,uses,resources,motion,voice,music,sfx,requirements) in enumerate(rows):
   slug=''.join(c for c in unicodedata.normalize('NFKD',name.lower()) if not unicodedata.combining(c)).replace('°','');slug='-'.join(slug.split())
   audio={'voice':voice,'music':music,'sfx':sfx,'mix':AUDIO}
   styles.append(dict(id=slug,name=name,family=family,familyName=title,kind=kind,signature=signature,exampleTopic=topic,uses=uses,resources=resources.split('; '),motion=motion,complexity='Alta',note='Estudo IA com produto fictício. Não demonstra fidelidade a um produto real nem execução de movimento ou som.',audio=audio,requirements=requirements,image=dict(atlas=f'assets/{family}.webp',column=i%4,row=i//4,columns=4,rows=3,source='Produto fictício gerado por IA'),preset=dict(version=2,skill='video-multimarcas',firstDelivery=['roteiro','storyboard visual','vídeo de 10 segundos para aprovação'],avatar=False,approvalGate='Aprovar os 10 segundos antes do vídeo completo.',productFidelity=LOCK,requiredAssets=requirements,audio=audio,research='Confirmar atributos em fontes oficiais do SKU; não inventar dados.',quality='Comparar produto e rótulo com o original em todo plano, inclusive transições; avaliar playback e áudio. Se houver alteração, corrigir ou substituir pelo recorte original.')))
